pub struct BackendV1Client<'a> { interface: Interface<'a> }
impl<'a> BackendV1Client<'a> {
    pub fn init(app: &'a App<'_>) -> Result<Self, Error> {
        let interface = Interface::new(app, MODULE_NAME, backend_v1_export_name, backend_v1_expectation)?;
        Self::checked(interface)
    }
    pub fn optional(app: &'a App<'_>) -> Result<Option<Self>, Error> {
        Interface::optional(app, MODULE_NAME, backend_v1_export_name, backend_v1_expectation)?.map(Self::checked).transpose()
    }
    fn checked(interface: Interface<'a>) -> Result<Self, Error> {
        if interface.slot_address(32).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(40).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(48).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(56).is_none() { return Err(Error::MissingSlot); }
        Ok(Self { interface })
    }
    /// Validates a driver-supplied profile; reported features describe encoding support, not physical qualification.
    /// # Safety
    /// Pure encoding into caller-owned output. No allocation, hardware access or retained pointers.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// profile: input, borrowed, lifetime call, nullable=false.
    /// output: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#negotiate(&self, r#profile: *const R4NvDeviceProfile, r#output: *mut R4NvFeatures) -> i32 {
        let function: BackendV1_negotiateFn = unsafe { self.interface.function(32) }.expect("admitted R4L slot");
        unsafe { function(r#profile, r#output) }
    }
    /// Encodes virtual CE copies and system-scope semaphore release. Validation precedes every output write.
    /// # Safety
    /// Pure encoding into caller-owned output. No allocation, hardware access or retained pointers.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// request: input, borrowed, lifetime call, nullable=false.
    /// commands: output, caller_owned, lifetime call, nullable=false.
    /// capacity: value, none, lifetime none, nullable=false.
    /// written: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#encode_copy(&self, r#request: *const R4NvCopy, r#commands: *mut u32, r#capacity: u32, r#written: *mut u32) -> i32 {
        let function: BackendV1_encode_copyFn = unsafe { self.interface.function(40) }.expect("admitted R4L slot");
        unsafe { function(r#request, r#commands, r#capacity, r#written) }
    }
    /// Encodes pitch/blocklinear conversion through C6B5/C7B5, bounded by max_layout_command_words. Original encode_copy and its limits remain available. No retained state or device access.
    /// # Safety
    /// Pure encoding into caller-owned output. No allocation, hardware access or retained pointers.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// request: input, borrowed, lifetime call, nullable=false.
    /// commands: output, caller_owned, lifetime call, nullable=false.
    /// capacity: value, none, lifetime none, nullable=false.
    /// written: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#encode_copy_layout(&self, r#request: *const R4NvCopyLayout, r#commands: *mut u32, r#capacity: u32, r#written: *mut u32) -> i32 {
        let function: BackendV1_encode_copy_layoutFn = unsafe { self.interface.function(48) }.expect("admitted R4L slot");
        unsafe { function(r#request, r#commands, r#capacity, r#written) }
    }
    /// Checks known C797/SM86 image layouts against texture/render/scanout use. Suggests an explicit compatible CE conversion for known readable views; never guesses an unknown modifier.
    /// # Safety
    /// Pure metadata negotiation; no allocation, maps, hardware access or retained pointers.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// profile: input, borrowed, lifetime call, nullable=false.
    /// request: input, borrowed, lifetime call, nullable=false.
    /// output: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#image_layout(&self, r#profile: *const R4NvDeviceProfile, r#request: *const R4NvImageRequest, r#output: *mut R4NvImagePlan) -> i32 {
        let function: BackendV1_image_layoutFn = unsafe { self.interface.function(56) }.expect("admitted R4L slot");
        unsafe { function(r#profile, r#request, r#output) }
    }
}

