pub const render_v1_expectation: Expectation = Expectation { interface_id_lo: 0x52344e56524e4452, interface_id_hi: 0x52344f5330373934, abi_major: 1, min_revision: 1, required_size: 56, known_required_flags: 0 };
pub const render_v1_export_name: &str = "RENDER_V1";
pub type RenderV1_render_infoFn = unsafe extern "C" fn(r#graphics_class: u32, r#output: *mut R4NvRenderInfo) -> i32;
pub type RenderV1_render_uploadFn = unsafe extern "C" fn(r#graphics_class: u32, r#bytes: *mut u8, r#capacity: u32, r#written: *mut u32) -> i32;
pub type RenderV1_encode_yuvFn = unsafe extern "C" fn(r#request: *const R4NvYuvRender, r#commands: *mut u32, r#capacity: u32, r#packets: *mut u8, r#packet_capacity: u32, r#written: *mut u32) -> i32;
/// Pure public fixed-render encoder for the native graphics producer. Color and YUV metadata policy remain with R4GFX. The canonical BO/VA and native queue owners retain all GPU resources through physical drain. No driver-private implementation imports are required by consumers.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct RenderV1 {
    pub header: InterfaceHeader,
    pub r#render_info: Option<RenderV1_render_infoFn>,
    pub r#render_upload: Option<RenderV1_render_uploadFn>,
    pub r#encode_yuv: Option<RenderV1_encode_yuvFn>,
}
const _: () = {
    assert!(core::mem::size_of::<RenderV1>() == 56);
    assert!(core::mem::align_of::<RenderV1>() == 8);
    assert!(core::mem::offset_of!(RenderV1, r#render_info) == 32);
    assert!(core::mem::offset_of!(RenderV1, r#render_upload) == 40);
    assert!(core::mem::offset_of!(RenderV1, r#encode_yuv) == 48);
};

